// Thứ tự:
// 1. Cấp phát node mới, next = NULL
// 2. Duyệt tmp từ head tới khi tmp->next == NULL (node cuối)
// 3. tmp->next = newNode
//
// Không tìm được node cuối nếu bỏ qua điều kiện tmp->next == NULL

void themcuoi(node *&head, int x){
    node *newNode = new node;
    newNode->data = x; newNode->next = NULL;
    if(head == NULL){ head = newNode; return; } // DSLK rỗng
    node *tmp = head;
    while(tmp->next != NULL) tmp = tmp->next;
    tmp->next = newNode;
}

node* themcuoi(node *head, int x){
    node *newNode = new node;
    newNode->data = x; newNode->next = NULL;
    if(head == NULL) return newNode;   // DSLK rỗng
    node *tmp = head;
    while(tmp->next != NULL) tmp = tmp->next;
    tmp->next = newNode;
    return head;
}

void themcuoi(LIST &l, int x){
    node *newNode = new node;
    newNode->data = x; newNode->next = NULL;
    if(l.head == NULL){
        l.head = newNode; l.tail = newNode;   // rỗng
    } else {
        l.tail->next = newNode;
        l.tail = newNode;
    }
}
